/**
 *
 * InputPassword is an enhanced input for password entry with strength metering, mask toggling, and controlled or uncontrolled usage.
 *
 * [Live Demo](https://www.primereact.org/inputpassword/)
 *
 * @module InputPassword
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { UseInputPasswordExposes, UseInputPasswordMaskChangeEvent, UseInputPasswordProps, UseInputPasswordState, UseInputPasswordValueChangeEvent } from '@primereact/types/headless/inputpassword';
/**
 * Defines passthrough(pt) options type in InputPassword component.
 */
export type InputPasswordPassThroughType<E> = PassThroughType<InputPasswordInstance, E>;
/**
 * Defines passthrough(pt) options of InputPassword component.
 */
export interface InputPasswordPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: InputPasswordPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Event fired when the password's value state changes.
 * @extends UseInputPasswordValueChangeEvent
 */
export interface InputPasswordValueChangeEvent extends UseInputPasswordValueChangeEvent<React.ChangeEvent<HTMLInputElement>> {
    /**
     * The new password value.
     */
    value: string;
}
/**
 * Event fired when the password's mask state changes.
 * @extends UseInputPasswordMaskChangeEvent
 */
export interface InputPasswordMaskChangeEvent extends UseInputPasswordMaskChangeEvent {
}
/**
 * Defines valid properties in InputPassword component.
 */
export interface InputPasswordProps extends BaseComponentProps<InputPasswordInstance, Omit<UseInputPasswordProps, 'onValueChange' | 'onMaskChange'>, InputPasswordPassThrough> {
    /**
     * Callback fired when the password value changes.
     * @param event The event that triggered the change.
     * @param event.originalEvent The original event that triggered the change.
     * @param event.value The value of the password input.
     * @returns void
     */
    onValueChange?: (event: InputPasswordValueChangeEvent) => void;
    /**
     * Callback fired when the mask state changes.
     * @param event The event that triggered the change.
     * @param event.value Whether the password is masked.
     * @returns void
     */
    onMaskChange?: (event: InputPasswordMaskChangeEvent) => void;
}
/**
 * Defines valid state in InputPassword component.
 * @extends UseInputPasswordState
 */
export interface InputPasswordState extends UseInputPasswordState {
}
/**
 * Defines the methods and properties exposed by InputPassword component.
 * @extends UseInputPasswordExposes
 */
export interface InputPasswordExposes extends UseInputPasswordExposes {
}
/**
 * Defines the CSS class names used in the InputPassword component.
 */
export declare const InputPasswordClassNames: {
    /**
     * Class name of the root element
     */
    readonly root: "p-password";
};
/**
 * Type representing the CSS class names used in the InputPassword component.
 */
export type InputPasswordClassNamesType = (typeof InputPasswordClassNames)[keyof typeof InputPasswordClassNames];
/**
 * Instance of InputPassword component.
 */
export type InputPasswordInstance = ComponentInstance<InputPasswordProps, InputPasswordState, InputPasswordExposes>;
